query:
mutation CreateTodo($title: String!, $description: String, $status: String = "TODO", $priority: String = "MEDIUM", $category: String = "PERSONAL", $dueDate: String) {
  createNode(
    tableId: "58"
    content: $title
    attributes: [
      { name: "title", value: $title }
      { name: "description", value: $description }
      { name: "status", value: $status }
      { name: "priority", value: $priority }
      { name: "category", value: $category }
      { name: "due_date", value: $dueDate }
      { name: "created_at", value: "{{ now }}" }
    ]
  ) {
    success
    node {
      id
      content
      attributes {
        name
        value
      }
    }
    errors {
      message
    }
  }
}
